#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

/* Return the index of the last Book item in the vector books where Book.pages is less than 100.
   If no such book exists, returns books.size().
*/
size_t findLastShortBook(std::vector<Book> const& books) {
    if (books.empty()) {
        return books.size();
    }

    // Use signed type for OpenMP loop variable and sentinel handling.
    long long lastIndex = -1;
    const long long n = static_cast<long long>(books.size());

    #pragma omp parallel for reduction(max:lastIndex)
    for (long long i = 0; i < n; ++i) {
        if (books[static_cast<size_t>(i)].pages < 100) {
            if (i > lastIndex) {
                lastIndex = i;
            }
        }
    }

    return (lastIndex >= 0) ? static_cast<size_t>(lastIndex) : books.size();
}
